257	func (c *Config) validate() error {
258		if c.Server.Protocol == HTTPS {
259			if c.Server.CertFile == "" {
260				return errors.New("cert_file cannot be empty when using HTTPS")
261			}
262	
263			if c.Server.CertKey == "" {
264				return errors.New("cert_key cannot be empty when using HTTPS")
265			}
266	
267			if _, err := os.Stat(c.Server.CertFile); os.IsNotExist(err) {
268				return fmt.Errorf("cannot find TLS cert_file at %q", c.Server.CertFile)
269			}
270	
271			if _, err := os.Stat(c.Server.CertKey); os.IsNotExist(err) {
272				return fmt.Errorf("cannot find TLS cert_key at %q", c.Server.CertKey)
273			}
274		}
275	
276		return nil
277	}
